const WORD_DATA = "";
const TRANSFORM_DATA = '';
const BITS = [0, 0, 0, 0, 10, 10, 11, 11, 10, 10, 10, 10, 10, 9, 9, 8, 7, 7, 8, 7, 7, 6, 6, 5, 5];
const OFFSETS = new Uint32Array(25);
for (let length = 4; length < 24; length++) OFFSETS[length + 1] = OFFSETS[length] + length * 2 ** BITS[length];
let dictionary, transforms;

function initialize(decodeBrotli) {
	if (dictionary) return;
	const decode = text => Uint8Array.from(atob(text), character => character.charCodeAt(0));
	dictionary = decodeBrotli(decode(WORD_DATA), 122784, {dictionary: false});
	dictionary.reverse();
	for (let i = 0; i < dictionary.length; i++) dictionary[i] ^= 128;
	const table = decode(TRANSFORM_DATA);
	transforms = [];
	for (let at = 0; at < table.length;) {
		const split = table.indexOf(0, at), end = table.indexOf(0, split + 2);
		transforms.push([table.subarray(at, split), table[split + 1], table.subarray(split + 2, end)]);
		at = end + 1;
	}
}

export function brotliDictionary(length, wordId, decodeBrotli) {
	if (!Number.isInteger(length) || length < 4 || length > 24 || !Number.isSafeInteger(wordId) || wordId < 0)
		throw new RangeError('The Brotli dictionary reference is invalid.');
	const count = 2 ** BITS[length], variant = Math.floor(wordId / count);
	if (variant > 120) throw new RangeError('The Brotli dictionary transformation is invalid.');
	initialize(decodeBrotli);
	const [prefix, operation, suffix] = transforms[variant];
	const first = operation >= 3 && operation <= 11 ? Math.min(length, operation - 2) : 0;
	const last = operation >= 12 ? Math.max(0, length - operation + 11) : length;
	const size = last - first, offset = OFFSETS[length] + (wordId % count) * length + first;
	const output = new Uint8Array(prefix.length + size + suffix.length);
	output.set(prefix);
	output.set(dictionary.subarray(offset, offset + size), prefix.length);
	const wordEnd = prefix.length + size;
	if (operation === 1 || operation === 2) {
		for (let at = prefix.length; at < wordEnd;) {
			const byte = output[at], width = byte < 192 ? 1 : byte < 224 ? 2 : 3;
			if (width === 1) {
				if (byte >= 97 && byte <= 122) output[at] -= 32;
			} else if (at + width <= wordEnd) output[at + width - 1] ^= width === 2 ? 32 : 5;
			if (operation === 1) break;
			at += width;
		}
	}
	output.set(suffix, wordEnd);
	return output;
}
